package bfs_test

import (
	"testing"

	"github.com/ai-verification/go-bfs/internal/bfs"
)

func TestDirectEdge(t *testing.T) {
	graph := map[int][]int{0: {1}, 1: {2}}
	path := bfs.ShortestPath(graph, 0, 1)
	if len(path) != 2 || path[0] != 0 || path[1] != 1 {
		t.Fatalf("expected [0 1], got %v", path)
	}
}

func TestShortestPath(t *testing.T) {
	graph := map[int][]int{
		0: {1, 2},
		1: {3},
		2: {3},
		3: {},
	}
	path := bfs.ShortestPath(graph, 0, 3)
	// both [0 1 3] and [0 2 3] are valid (length 3)
	if len(path) != 3 || path[0] != 0 || path[len(path)-1] != 3 {
		t.Fatalf("expected path of length 3 from 0 to 3, got %v", path)
	}
}

func TestSameNode(t *testing.T) {
	graph := map[int][]int{0: {1}}
	path := bfs.ShortestPath(graph, 0, 0)
	if len(path) != 1 || path[0] != 0 {
		t.Fatalf("expected [0], got %v", path)
	}
}

func TestUnreachable(t *testing.T) {
	graph := map[int][]int{0: {1}, 2: {3}}
	path := bfs.ShortestPath(graph, 0, 3)
	if path != nil {
		t.Fatalf("expected nil for unreachable path, got %v", path)
	}
}

func TestLongerPath(t *testing.T) {
	graph := map[int][]int{
		0: {1},
		1: {2},
		2: {3},
		3: {4},
		4: {},
	}
	path := bfs.ShortestPath(graph, 0, 4)
	expected := []int{0, 1, 2, 3, 4}
	if len(path) != len(expected) {
		t.Fatalf("expected %v, got %v", expected, path)
	}
	for i, v := range expected {
		if path[i] != v {
			t.Fatalf("path[%d]: expected %d, got %d", i, v, path[i])
		}
	}
}
